//! Parity tests against the Go original (`github.com/junhinhow/charm-dialog`).
//!
//! The golden file is generated by the Go program in
//! `reference/go/charm-dialog/cmd/parity`:
//!
//! ```text
//! cargo run -p charm-parity --bin parity -- gen \
//!     crates/charm-dialog/tests/golden/dialog.txt -- \
//!     go run ./reference/go/charm-dialog/cmd/parity
//! ```
//!
//! [`build_report`] mirrors that Go program line by line, so the two outputs
//! must match after ANSI codes are removed.

use std::fmt::Write as _;

use charm_dialog::Dialog;
use charm_parity::assert_golden;

/// Builds the dialogs in the same order as the Go parity program.
fn cases() -> Vec<(&'static str, Dialog)> {
    let mut input = Dialog::new_input("Entrada", "Digite seu nome:");
    input.input_value.push_str("Ana");

    vec![
        (
            "confirm",
            Dialog::new_confirm("Confirmar", "Deseja continuar?"),
        ),
        ("alert", Dialog::new_alert("Aviso", "Operacao concluida")),
        ("input", input),
        (
            "custom",
            Dialog::new_custom(
                "Opcoes",
                "Escolha uma acao",
                &["Salvar", "Descartar", "Cancelar"],
            ),
        ),
        ("empty", Dialog::new_custom("Vazio", "Sem botoes", &[])),
    ]
}

/// Builds the human readable report, mirroring the Go parity program.
fn build_report() -> String {
    let mut out = String::new();

    for (name, dialog) in cases() {
        let _ = writeln!(out, "== {name} ==");
        let _ = writeln!(out, "title={}", dialog.title);
        let _ = writeln!(out, "buttons={}", dialog.buttons.join("|"));
        let _ = writeln!(out, "selected={}", dialog.selected);
        let _ = writeln!(out, "selected_button={}", dialog.selected_button());
        // Widths below the button row are left out: Go can exceed them there.
        for width in [0, 40, 80] {
            let _ = writeln!(out, "render[{width}]:");
            let _ = writeln!(out, "{}", dialog.render(width));
        }
        let _ = writeln!(out, "overlay[80x24]:");
        let _ = writeln!(out, "{}", dialog.render_overlay(80, 24));
        let _ = writeln!(out, "overlay[40x6]:");
        let _ = writeln!(out, "{}", dialog.render_overlay(40, 6));
    }

    let _ = writeln!(out, "== navigation ==");
    let mut nav = Dialog::new_custom("Nav", "Use setas", &["A", "B", "C"]);
    for step in ["next", "next", "next", "prev", "prev", "prev", "prev"] {
        if step == "next" {
            nav.next_button();
        } else {
            nav.prev_button();
        }
        let _ = writeln!(
            out,
            "{step} selected={} button={}",
            nav.selected,
            nav.selected_button()
        );
    }

    out
}

#[test]
fn dialog_report_matches_go() {
    assert_golden("dialog", &build_report());
}

#[test]
fn navigation_clamps_at_the_edges_like_go() {
    let mut d = Dialog::new_custom("Nav", "x", &["A", "B", "C"]);
    for _ in 0..5 {
        d.next_button();
    }
    assert_eq!(d.selected_button(), "C");
    for _ in 0..5 {
        d.prev_button();
    }
    assert_eq!(d.selected_button(), "A");
}
